import numpy as np
from scipy.optimize import minimize

def f_pos(z):
    return 2.5*z - 4.5*z**3 - 4*np.sqrt((1-z**2)/2)

def f_neg(z):
    return 2.5*z - 4.5*z**3 + 4*np.sqrt((1-z**2)/2)

# We'll check the minimum of both on [-1, 1]
# To be safe, we'll check many starting points.
min_f = 100
for start_z in np.linspace(-1, 1, 100):
    res_pos = minimize(f_pos, start_z, bounds=[(-1, 1)])
    if res_pos.success:
        min_f = min(min_f, f_pos(res_pos.x[0]))
    res_neg = minimize(f_neg, start_z, bounds=[(-1, 1)])
    if res_neg.success:
        min_f = min(min_f, f_neg(res_neg.x[0]))

print(f"Minimum f found: {min_f}")
